service:
if [ -d /run/systemd/system ] && command -v systemctl >/dev/null 2>&1; then init=systemd
elif command -v rc-service >/dev/null 2>&1; then init=openrc
elif command -v service >/dev/null 2>&1; then init=sysv
else init=none
fi
echo "init=$init"
case "$init" in
  systemd) systemctl 'restart' -- 'nginx' ;;
  openrc) rc-service 'nginx' 'restart' ;;
  sysv) service 'nginx' 'restart' ;;
  *) echo 'No service manager found: no systemd, OpenRC or service command.' >&2; exit 47 ;;
esac
